class Solution {
  int leftMax;
  int rightMax;

  public int[] treeQueries(TreeNode root, int[] queries) {
    leftMax = 0;
    rightMax = 0;

    int[] allL = new int[100001];
    int[] res = new int[queries.length];

    dfsLeft(root, 0, allL);
    dfsRight(root, 0, allL);

    for (int i = 0; i < queries.length; i++) {
      res[i] = allL[queries[i]];
    }
    return res;
  }

  public void dfsLeft(TreeNode root, int level, int[] allL) {
    if (root == null) return;
    allL[root.val] = leftMax;
    leftMax = Math.max(leftMax, level);
    dfsLeft(root.left, level + 1, allL);
    dfsLeft(root.right, level + 1, allL);
  }

  public void dfsRight(TreeNode root, int level, int[] allL) {
    if (root == null) return;
    allL[root.val] = Math.max(rightMax, allL[root.val]);
    rightMax = Math.max(rightMax, level);
    dfsRight(root.right, level + 1, allL);
    dfsRight(root.left, level + 1, allL);
  }
}
